/**
 * The server-side reads of the public requirements catalogue (the pages /requirements and /requirements/[code]).
 * Same rule as lib/api.ts: with DG_API_URL set they call the API; unset, the site builds from the mock
 * (lib/mock/requirements.json, generated by `python -m dgate.readiness.export` from the same seed and checked
 * by a backend test, so it cannot drift from the rules).
 */
import { REVALIDATE_SECONDS, ApiError } from './api';
import mock from './mock/requirements.json';
import type { RequirementDetail, RequirementSummary } from './readiness-types';
import { DEMAND_COUNTRIES, SAMPLE_CPV, isDemand, type Demand } from './demand';

const API_BASE = process.env.DG_API_URL;

interface Catalogue { items: RequirementSummary[]; total: number; meta: { rulesReviewed: string } }

async function get<T>(path: string): Promise<T | null> {
  const res = await fetch(`${API_BASE}${path}`, {
    headers: { accept: 'application/json' }, signal: AbortSignal.timeout(20_000), next: { revalidate: REVALIDATE_SECONDS },
  });
  if (res.status === 404) return null;
  if (!res.ok) throw new ApiError(res.status, `GET ${path} failed`);
  return (await res.json()) as T;
}

export async function getRequirements(): Promise<Catalogue> {
  if (API_BASE) {
    const r = await get<Catalogue>('/v1/requirements');
    if (r === null) throw new ApiError(404, 'GET /v1/requirements returned 404');
    return r;
  }
  return mock.catalogue as unknown as Catalogue;
}

/**
 * WP-68: the demand map for the sample codes of /readiness/spain-automotive, read live from the API (POST /v1/readiness/demand, stateless:
 * nothing of a visitor is in it). Null on a build without an API (the demo data is not live, so no figure is shown) and on any failure.
 */
export async function getDemandSample(): Promise<Demand | null> {
  if (!API_BASE) return null;
  try {
    const res = await fetch(`${API_BASE}/v1/readiness/demand`, {
      method: 'POST', headers: { 'content-type': 'application/json', accept: 'application/json' },
      body: JSON.stringify({ cpv: [...SAMPLE_CPV], countries: [...DEMAND_COUNTRIES] }),
      signal: AbortSignal.timeout(10_000), next: { revalidate: REVALIDATE_SECONDS },
    });
    if (!res.ok) return null;
    const body: unknown = await res.json();
    return isDemand(body) ? body : null;
  } catch {
    return null;
  }
}

/** One requirement by its code (`REQ-NCAGE`), or null when there is none. */
export async function getRequirement(code: string): Promise<RequirementDetail | null> {
  if (API_BASE) return get<RequirementDetail>(`/v1/requirements/${encodeURIComponent(code)}`);
  const found = (mock.requirements as Record<string, unknown>)[code];
  return (found as RequirementDetail | undefined) ?? null;
}
